{
  "action": "conclude",
  "message_to_patient": "متأسفم که این‌قدر اذیت هستید. سردرد ناگهانی و بسیار شدید، «بدترین سردرد عمرتان» همراه با استفراغ، می‌تواند نشانه‌ی یک مشکل جدی مثل خون‌ریزی در مغز باشد و نباید منتظر بمانید. لطفاً همین الان با اورژانس ۱۱۵ تماس بگیرید یا هرچه سریع‌تر به نزدیک‌ترین اورژانس بیمارستان بروید. خودتان رانندگی نکنید و اگر کسی همراه شماست، او را در جریان بگذارید. اگر ضعف یا بی‌حسی، تاری یا دوبینی، اختلال حرف زدن، تشنج، گردن‌درد و خشکی گردن یا کاهش هوشیاری پیدا کردید، فوراً به اورژانس اطلاع دهید.",
  "reasoning_note": "Thunderclap onset of worst headache of life with vomiting 2 hours ago: subarachnoid hemorrhage until proven otherwise; other can't-miss causes include intracerebral hemorrhage, dissection, and meningitis. Emergency conclusion without further questions.",
  "assessment": {
    "triage_level": "EMERGENCY_NOW",
    "emergency_probability": 0.95,
    "specialty_primary": "emergency_medicine",
    "specialty_secondary": "neurology",
    "differential": [
      {
        "name_fa": "خون‌ریزی زیر عنکبوتیه",
        "name_en": "Subarachnoid hemorrhage",
        "probability": 0.5,
        "supporting": [
          "ناگهانی بودن شروع (thunderclap)",
          "بدترین سردرد عمر",
          "استفراغ"
        ],
        "against": [
          "هنوز شواهد نورولوژیک بررسی نشده"
        ]
      },
      {
        "name_fa": "خون‌ریزی داخل مغز",
        "name_en": "Intracerebral hemorrhage",
        "probability": 0.15,
        "supporting": [
          "سردرد شدید ناگهانی",
          "استفراغ"
        ],
        "against": [
          "ذکر نشدن ضعف یا علائم کانونی"
        ]
      },
      {
        "name_fa": "دایسکشن شریان گردن/مغز یا سندرم انقباض عروق مغزی",
        "name_en": "Cervical/cerebral artery dissection or reversible cerebral vasoconstriction syndrome",
        "probability": 0.1,
        "supporting": [
          "سردرد ناگهانی شدید"
        ],
        "against": [
          "اطلاعات ضربه یا مصرف داروها موجود نیست"
        ]
      },
      {
        "name_fa": "مننژیت",
        "name_en": "Meningitis",
        "probability": 0.05,
        "supporting": [
          "سردرد و استفراغ"
        ],
        "against": [
          "شروع رعدآسا، تب ذکر نشده"
        ]
      },
      {
        "name_fa": "میگرن شدید",
        "name_en": "Severe migraine",
        "probability": 0.08,
        "supporting": [
          "سردرد شدید با استفراغ"
        ],
        "against": [
          "شروع ناگهانی و بی‌سابقه بودن"
        ]
      }
    ],
    "cant_miss": [
      {
        "name_fa": "خون‌ریزی زیر عنکبوتیه",
        "name_en": "Subarachnoid hemorrhage",
        "status": "suspected",
        "reason": "سردرد رعدآسا و بدترین سردرد زندگی با استفراغ"
      },
      {
        "name_fa": "سکته مغزی خونریزی‌دهنده",
        "name_en": "Hemorrhagic stroke",
        "status": "not_excluded",
        "reason": "علائم عصبی کانونی هنوز بررسی نشده است"
      },
      {
        "name_fa": "مننژیت",
        "name_en": "Meningitis",
        "status": "not_excluded",
        "reason": "تب و سفتی گردن پرسیده نشده است"
      }
    ],
    "missing_information": [
      "سن و جنس",
      "سابقه فشار خون و مصرف داروها (مثل رقیق‌کننده خون)",
      "ضربه به سر",
      "علائم عصبی کانونی، تب، سفتی گردن"
    ],
    "confidence": "high",
    "out_of_scope_pediatric": false,
    "patient_message": "سردرد ناگهانی و بسیار شدید با استفراغ نیاز به بررسی فوری در اورژانس دارد. لطفاً همین الان با ۱۱۵ تماس بگیرید یا به نزدیک‌ترین اورژانس بروید.",
    "clinical_summary": {
      "chief_complaint": "سردرد ناگهانی بسیار شدید",
      "history_of_present_illness": "حدود ۲ ساعت پیش سردرد ناگهانی و شدید شروع شد که بیمار آن را بدترین سردرد زندگی‌اش توصیف می‌کند. یک بار استفراغ داشته است.",
      "relevant_history": "گزارش نشده",
      "medications": "گزارش نشده",
      "allergies": "گزارش نشده",
      "pertinent_negatives": "بررسی نشده",
      "assessment_rationale": "شروع رعدآسا با استفراغ تا اثبات خلاف، خون‌ریزی زیر عنکبوتیه یا سایر علل عروقی مغز را مطرح می‌کند و نیاز به تصویربرداری و ارزیابی فوری در اورژانس دارد."
    }
  }
}

